131	async function calculateElevation(stair: Stair, detail: HTMLElement) {
132	  const button = detail.querySelector<HTMLButtonElement>('#elevation-button');
133	  const value = detail.querySelector<HTMLElement>('#elevation-value');
134	  const note = detail.querySelector<HTMLElement>('#elevation-note');
135	  if (!button || !value || !note || stair.lat === null || stair.lng === null) return;
136	  button.disabled = true;
137	  button.hidden = true;
138	  value.textContent = 'Calculating…';
139	  note.textContent = 'Looking up an endpoint and sampling the elevation path.';
140	  const params = new URLSearchParams({ version: '3', lat: String(stair.lat), lng: String(stair.lng), description: stair.name.slice(0, 500) });
141	  try {
142	    const response = await fetch(`/api/elevation?${params}`);
143	    const result = await response.json() as { available?: boolean; gainFeet?: number; descentFeet?: number; verticalFeet?: number; startFeet?: number; endFeet?: number; endpoint?: string; estimatedSteps?: number; method?: 'inferred-path' | 'local-range'; reason?: string };
144	    if (!response.ok || !result.available) throw new Error(result.reason || 'Elevation data is unavailable for this entry.');
145	    value.textContent = result.method === 'inferred-path' ? (result.gainFeet! >= result.descentFeet! ? `~${result.gainFeet} ft uphill` : `~${result.descentFeet} ft downhill`) : `~${result.gainFeet} ft change`;
146	    note.textContent = result.method === 'inferred-path' ? `Estimated from ${result.startFeet} ft to ${result.endFeet} ft toward ${result.endpoint}.` : 'Estimated from Google elevation samples within 45 m of the mapped location.';
147	    if (!stair.steps) {
148	      const stepCount = detail.querySelector<HTMLElement>('#step-count');
149	      const stepNote = detail.querySelector<HTMLElement>('#step-note');
150	      if (stepCount && stepNote) {
151	        stepCount.textContent = `~${result.estimatedSteps} steps`;
152	        stepNote.textContent = 'Estimated from Google elevation using a 7 in riser.';
153	      }
154	    }
155	  } catch (error) {
156	    value.textContent = 'No estimate available';
157	    note.textContent = error instanceof Error ? error.message : 'Elevation data is unavailable for this entry.';
158	  } finally {
159	    button.hidden = true;
160	  }
161	}
162	function handleImages(parent: HTMLElement) {
163	  parent.querySelectorAll<HTMLImageElement>('img').forEach(img => img.addEventListener('error', () => {img.hidden = true; img.parentElement?.classList.add('image-unavailable');}, {once: true}));
164	}
