146	   146	    note.textContent = result.method === 'inferred-path' ? `Estimated from ${result.startFeet} ft to ${result.endFeet} ft toward ${result.endpoint}.` : 'Estimated from Google elevation samples within 45 m of the mapped location.';
147	   147	    if (!stair.steps) {
