  1	import L from 'leaflet';
  2	import 'leaflet/dist/leaflet.css';
  3	import './style.css';
  4	import './route-planner.css';
  5	import './multi-neighborhood.css';
  6	const { default: dataset } = await import('./stairs.json');
  7	
  8	type Stair = (typeof dataset.stairs)[number];
  9	type RouteStop = Stair & { lat: number; lng: number };
 10	const stairs: Stair[] = dataset.stairs;
 11	const colors = ['#242923', '#0288d1', '#558b2f', '#d2ad00', '#f57c00', '#e65100'];
 12	const labels = ['Needs verification', 'Simple & functional', 'Neighborhood character', 'Hidden gems', 'Something special', 'The Scheherazade category'];
 13	const legendDescriptions = [
 14	  'Black markers need verification or an addition to the source spreadsheet.',
 15	  'The most ordinary stairways in the index.',
 16	  'Part of the neighborhood’s history and everyday life. The setting or view may be the main attraction.',
 17	  'Lesser-known stairways in especially attractive surroundings.',
 18	  'Impressive design or an outstanding feature, with only minor shortcomings.',
 19	  'Stairways that surprise, spark the imagination, and delight the senses. Elegant or rustic, short or long.'
 20	];
 21	const sourceSheet = 'https://docs.google.com/spreadsheets/d/REDACTED/edit?gid=0';
 22	const sourceMap = 'https://www.google.com/maps/d/viewer?REDACTED';
 23	const icon = (name: string, size = 20) => {
 24	  const paths: Record<string, string> = {
 25	    stairs: '<path d="M3 21h6v-6h6V9h6V3"/>',
 26	    search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 27	    arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>',
 28	    pin: '<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 29	    camera: '<path d="M3 7h4l2-3h6l2 3h4v13H3Z"/><circle cx="12" cy="13" r="4"/>',
 30	    locate: '<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',
 31	    close: '<path d="m6 6 12 12M6 18 18 6"/>',
 32	    shuffle: '<path d="m3 5 5 0 8 14h5m-5-4 5 4-5 4M3 19h5L16 5h5m-5-4 5 4-5 4"/>',
 33	    route: '<path d="M4 18c3-1 3-11 7-11s3 10 7 9 2-6 3-8"/><circle cx="4" cy="18" r="2"/><circle cx="21" cy="8" r="2"/>',
 34	    external: '<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',
 35	    elevation: '<path d="M3 19 9 9l4 6 3-4 5 8"/><path d="M3 21h18"/>'
 36	  };
 37	  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.stairs}</svg>`;
 38	};
 39	const escape = (value: string) => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]!));
 40	function el<T extends HTMLElement>(selector: string): T {
 41	  const node = document.querySelector<T>(selector);
 42	  if (!node) throw new Error(`Missing element: ${selector}`);
 43	  return node;
 44	}
 45	const neighborhoods = [...new Set(stairs.map(stair => stair.neighborhood))].sort();
