 52	let photosOnly = false;
 53	let visible: Stair[] = [];
 54	let selected: Stair | undefined;
 55	let pageSize = 45;
 56	let nearbyOrigin: L.LatLng | undefined;
 57	let userMarker: L.CircleMarker | undefined;
 58	let routeStops: RouteStop[] = [];
 59	let routeArea = 'all';
 60	let routePreference = 'best';
 61	
 62	el('#app').innerHTML = `
 63	  <header class="header">
 64	    <a class="brand" href="/" aria-label="SF Stairs home"><span class="brand-icon">${icon('stairs', 28)}</span><span>sf stairs<span class="brand-dot">.</span></span></a>
 65	    <div class="header-note">A FIELD GUIDE TO THE CITY’S STAIRWAYS</div>
 66	    <button id="about-button" class="text-button">The story behind the steps ${icon('arrow', 16)}</button>
 67	  </header>
 68	  <main>
