.map-legend>div{padding-top:12px}
.map-legend>div>div{display:flex;align-items:center;gap:7px;margin-bottom:9px;font-size:9px}
.map-legend b{width:7px}
.map-legend button{font-size:9px;text-decoration:underline;color:#6a755e;padding:4px 0}
.map-legend{left:10px;width:190px;font-size:10px}
== .eyebrow
.eyebrow{font-size:10px;letter-spacing:1.8px;font-weight:700;display:flex;gap:8px;align-items:center}
.eyebrow>span{width:6px;height:6px;border-radius:50%;background:var(--orange)}
.eyebrow{font-size:9px;padding-right:18px;line-height:1.5}
.eyebrow{font-size:8px}
== .notice
.notice{font-size:11px;background:#f4e8cf;padding:10px;line-height:1.6}
== .filter-bar
.filter-bar{display:flex;align-items:center;gap:15px;padding:14px 20px;border-bottom:1px solid var(--border);min-height:62px}
.filter-bar{gap:12px}
.filter-bar{padding:12px;gap:9px;flex-wrap:wrap}
== .detail-content
.detail-content{padding:24px 20px}
.detail-content{padding:20px 15px}
== .card-meta
.card-meta{display:block;font-size:9px;color:#818b77;margin-top:6px;line-height:1.5}
.card-meta>span{display:inline-flex;align-items:center;gap:4px}
== .rating-tag
.rating-tag{background:var(--dot);color:#fff;padding:4px 7px;border-radius:3px}
== .detail 
.detail h2{font-size:22px;line-height:1.35;margin:12px 0 16px;letter-spacing:-.7px}
.detail .eyebrow{font-size:9px;padding-right:18px;line-height:1.5}
.detail h2{font-size:20px}

